from __future__ import annotations

import sys
from pathlib import Path


def main() -> int:
    version = sys.argv[1].strip() if len(sys.argv) > 1 else "dev"
    if not version:
        version = "dev"

    target = Path(__file__).resolve().parents[1] / "qt_app" / "_build_version.py"
    target.write_text(
        "# This file is generated by scripts/write_build_version.py during packaging.\n"
        f"APP_VERSION = {version!r}\n",
        encoding="utf-8",
    )
    print(f"Wrote build version {version} to {target}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
